.fasilitas-card {
  display: flex;
  background: var(--white);
  border-radius: var(--card-radius);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
  border: 1px solid rgba(0, 0, 0, 0.03);
  height: 200px;
  transition: var(--transition-smooth);
}

.fasilitas-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-hover);
  border-color: rgba(0, 141, 76, 0.15);
}

.fasilitas-img-wrapper {
  width: 40%;
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}

.fasilitas-img-wrapper img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: var(--transition-smooth);
}

.fasilitas-card:hover .fasilitas-img-wrapper img {
  transform: scale(1.08);
}

.fasilitas-content {
  width: 60%;
  padding: 25px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.fasilitas-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.fasilitas-title i {
  color: var(--primary-color);
}

.fasilitas-desc {
  font-size: 0.85rem;
  margin-bottom: 0;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* --- Lokasi & Kontak --- */
.lokasi-card {
  padding: 40px;
}

.map-container {
  border-radius: 15px;
  overflow: hidden;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
  border: 1px solid rgba(0,0,0,0.05);
}

.map-container iframe {
  display: block;
}

.contact-info-list {
  list-style: none;
  padding-left: 0;
  margin-bottom: 0;
}

.contact-info-list li {
  display: flex;
  align-items: flex-start;
  gap: 15px;
  margin-bottom: 20px;
}

.contact-info-list li:last-child {
  margin-bottom: 0;
}

.contact-icon-box {
  width: 45px;
  height: 45px;
  background: rgba(0, 141, 76, 0.08);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary-color);
  font-size: 1.2rem;
  flex-shrink: 0;
  transition: var(--transition-smooth);
}

.contact-info-list li:hover .contact-icon-box {
  background: var(--primary-gradient);
  color: var(--white);
  transform: translateY(-2px);
}

.contact-text-box h6 {
  font-size: 0.95rem;
  margin-bottom: 3px;
  color: var(--text-dark);
}

.contact-text-box p {
  font-size: 0.9rem;
  margin-bottom: 0;
}

/* --- Premium Footer --- */
.footer-premium {
  background-color: #073b20;
  background-image: linear-gradient(180deg, #0B6B3A 0%, #052615 100%);
  color: rgba(255, 255, 255, 0.8);
  padding: 80px 0 30px;
  border-top: 5px solid var(--accent-color);
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-bottom: 25px;
}

.footer-brand img {
  height: 60px;
  width: auto;
}

.footer-brand-title {
  display: flex;
  flex-direction: column;
}

.footer-brand-name {
  color: var(--white);
  font-size: 1.4rem;
  font-weight: 800;
  line-height: 1.2;
}

.footer-brand-sub {
  color: var(--accent-color);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.footer-desc {
  font-size: 0.9rem;
  line-height: 1.8;
  margin-bottom: 25px;
  color: rgba(255, 255, 255, 0.7);
}

.footer-title {
  color: var(--white);
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 25px;
